-- Merchant Lending (on-ground) team: employee codes (FSE Ecode, column B of LRM_Manpower_28th_Final,
-- TL_SGL tab, 253 people). Onboarding cases whose "sold by" employee code (from CT) is on this list
-- show in yellow in the onboarding case list so the team prioritises them. Additive only.
CREATE TABLE IF NOT EXISTS merchant_lending_ecodes(
  employee_code TEXT PRIMARY KEY,
  added_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
